{"file_path": "/Users/juliusolsson/Desktop/Development/win-win/.claude/worktrees/simplify/app/(owner)/oversikt/page.tsx", "content": "import Link from "next/link";
import { ArrowRight, TrendingUp } from "lucide-react";
import Frame from "../../_components/Frame";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { account, kr, ownerFeeForBooking } from "../../_data/mock";
import { getOwnerComplianceCenter } from "@/server/services/compliance-service";
import {
  getOwnerBookings,
  getOwnerEconomy,
  getOwnerIssues,
  getOwnerProperties,
} from "@/server/services/owner-portal-service";

function Sparkline({ values, up = true }: { values: number[]; up?: boolean }) {
  const max = Math.max(1, ...values);
  const min = Math.min(...values);
  const range = Math.max(1, max - min);
  const pts = values
    .map((v, i) => {
      const x = (i / (values.length - 1)) * 100;
      const y = 28 - ((v - min) / range) * 24 - 2;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");
  const color = up ? "var(--success)" : "var(--primary)";
  return (
    <svg viewBox="0 0 100 30" preserveAspectRatio="none" className="h-10 w-full">
      <polyline points={pts} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export default async function Oversikt() {
  const [bookings, properties, issues, complianceCenter, economy] =
    await Promise.all([
      getOwnerBookings(),
      getOwnerProperties(),
      getOwnerIssues(),
      getOwnerComplianceCenter(),
      getOwnerEconomy(),
    ]);

  const propertyById = new Map(properties.map((p) => [p.id, p]));
  const kommande = bookings.filter((b) => b.state === "Kommande").length;
  const pagaende = bookings.filter((b) => b.state === "Pågående").length;
  const avslutade = bookings.filter((b) => b.state === "Avslutad").length;

  // Things that need the owner's attention, with a plain category.
  type Item = { id: string; title: string; category: string; href: string };
  const attention: Item[] = [
    ...issues
      .filter((d) => d.status === "Öppen")
      .map((d) => ({
        id: `issue-${d.id}`,
        title: `${d.kind} · ${d.unitLabel}`,
        category: "Störning",
        href: `/storningar/${d.id}`,
      })),
    ...complianceCenter.compliance
      .filter((c) => c.status !== "Följs")
      .map((c) => ({
        id: `rule-${c.id}`,
        title: `${c.title} · ${c.propertyName}`,
        category: "Regelavvikelse",
        href: `/regler/kontroller/${c.id}`,
      })),
    ...bookings
      .filter((b) => b.contract === "Väntar" && b.state !== "Avslutad")
      .map((b) => ({
        id: `contract-${b.id}`,
        title: `Avtal saknas · ${b.guest} · ${b.unitLabel}`,
        category: "Avtal",
        href: `/bokningar/${b.id}`,
      })),
  ];

  // Föreningsavgift / ägaravgift earned this year, and a simple full-year forecast.
  const feeFor = (b: (typeof bookings)[number]) => {
    const p = propertyById.get(b.propertyId);
    if (!p) return 0;
    return ownerFeeForBooking(p, b.nights, b.nights * b.nightly);
  };
  const intjanat = bookings
    .filter((b) => b.state !== "Avbokad")
    .reduce((sum, b) => sum + feeFor(b), 0);
  const MONTH_OF_YEAR = 6; // juni
  const prognos = Math.round((intjanat / MONTH_OF_YEAR) * 12);
  const trend = economy.rows.map((r) => r.share);
  const forecastTrend = [...trend, Math.round(trend[trend.length - 1] * 1.25)];

  return (
    <Frame crumb={<span className="font-semibold text-foreground">Översikt</span>}>
      <div className="mb-7">
        <div className="text-xs font-semibold uppercase tracking-wide text-primary">
          {account.org}
        </div>
        <h1 className="mt-1 font-display text-[28px] font-semibold tracking-tight">
          God morgon, Erik.
        </h1>
      </div>

      {/* UTHYRNING */}
      <SectionLabel>Uthyrning</SectionLabel>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <StatCard label="Kommande" value={kommande} detail="bokade vistelser" />
        <StatCard label="Pågående" value={pagaende} detail="just nu" accent />
        <StatCard label="Avslutade i år" value={avslutade} detail="genomförda" />
      </div>

      {/* BEHÖVER DIN UPPMÄRKSAMHET */}
      <SectionLabel className="mt-9">Behöver din uppmärksamhet</SectionLabel>
      <Card className="overflow-hidden">
        {attention.length > 0 ? (
          <div className="divide-y">
            <div className="flex items-center gap-3 bg-muted/40 px-5 py-2.5 text-[12px] font-semibold uppercase tracking-wide text-muted-foreground">
              <span className="flex-1">Åtgärd</span>
              <span className="w-36 shrink-0">Kategori</span>
            </div>
            {attention.map((item) => (
              <Link
                key={item.id}
                href={item.href}
                className="flex items-center gap-3 px-5 py-3.5 transition-colors hover:bg-muted/50"
              >
                <span className="size-2 shrink-0 rounded-full bg-[var(--warning)]" />
                <span className="min-w-0 flex-1 truncate text-sm font-medium">
                  {item.title}
                </span>
                <span className="w-36 shrink-0">
                  <Badge variant={item.category === "Störning" ? "warning" : "outline"}>
                    {item.category}
                  </Badge>
                </span>
                <ArrowRight className="size-4 shrink-0 text-muted-foreground" />
              </Link>
            ))}
          </div>
        ) : (
          <CardContent className="flex flex-col items-center justify-center py-12 text-center">
            <div className="text-[15px] font-semibold">Allt är under kontroll</div>
            <p className="mt-1 text-[13.5px] text-muted-foreground">
              Inget behöver din uppmärksamhet just nu.
            </p>
          </CardContent>
        )}
      </Card>

      {/* EKONOMI */}
      <SectionLabel className="mt-9">Ekonomi</SectionLabel>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div className="text-[13.5px] font-medium text-muted-foreground">
                Intjänat i år
              </div>
              <Badge variant="muted">föreningsavgift</Badge>
            </div>
            <div className="mt-2 font-display text-4xl font-semibold tracking-tight">
              {kr(intjanat)}
            </div>
            <div className="mt-3">
              <Sparkline values={trend} />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div className="text-[13.5px] font-medium text-muted-foreground">
                Prognos · helår
              </div>
              <span className="flex items-center gap-1 text-[13px] font-semibold text-[var(--success)]">
                <TrendingUp className="size-4" /> est.
              </span>
            </div>
            <div className="mt-2 font-display text-4xl font-semibold tracking-tight">
              {kr(prognos)}
            </div>
            <div className="mt-3">
              <Sparkline values={forecastTrend} />
            </div>
          </CardContent>
        </Card>
      </div>
    </Frame>
  );
}

function SectionLabel({
  children,
  className = "",
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div
      className={`mb-3 text-xs font-bold uppercase tracking-[0.1em] text-muted-foreground ${className}`}
    >
      {children}
    </div>
  );
}

function StatCard({
  label,
  value,
  detail,
  accent = false,
}: {
  label: string;
  value: number;
  detail: string;
  accent?: boolean;
}) {
  return (
    <Card className={accent ? "border-primary/20 bg-accent/30" : undefined}>
      <CardContent className="p-6">
        <div className="text-[13.5px] font-medium text-muted-foreground">{label}</div>
        <div className="mt-2 font-display text-5xl font-semibold tracking-tight">
          {value}
        </div>
        <div className="mt-2 text-[13.5px] text-muted-foreground">{detail}</div>
      </CardContent>
    </Card>
  );
}
"}

