import {
  getOwnerBookings,
  getOwnerEconomy,
  getOwnerIssues,
  getOwnerProperties,
} from "@/server/services/owner-portal-service";

function Sparkline({ values, up = true }: { values: number[]; up?: boolean }) {
  const max = Math.max(1, ...values);
  const min = Math.min(...values);
  const range = Math.max(1, max - min);
  const pts = values
    .map((v, i) => {
      const x = (i / (values.length - 1)) * 100;
      const y = 28 - ((v - min) / range) * 24 - 2;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");
  const color = up ? "var(--success)" : "var(--primary)";
  return (
    <svg viewBox="0 0 100 30" preserveAspectRatio="none" className="h-10 w-full">
      <polyline points={pts} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export default async function Oversikt() {
  const [bookings, properties, issues, complianceCenter, economy] =
    await Promise.all([
      getOwnerBookings(),
      getOwnerProperties(),
      getOwnerIssues(),
      getOwnerComplianceCenter(),
      getOwnerEconomy(),
    ]);

  const propertyById = new Map(properties.map((p) => [p.id, p]));
  const kommande = bookings.filter((b) => b.state === "Kommande").length;
  const pagaende = bookings.filter((b) => b.state === "Pågående").length;
  const avslutade = bookings.filter((b) => b.state === "Avslutad").length;

  // Things that need the owner's attention, with a plain category.
  type Item = { id: string; title: string; category: string; href: string };
  const attention: Item[] = [
    ...issues
      .filter((d) => d.status === "Öppen")
      .map((d) => ({
        id: `issue-${d.id}`,
        title: `${d.kind} · ${d.unitLabel}`,
        category: "Störning",
        href: `/storningar/${d.id}`,
      })),
    ...complianceCenter.compliance
      .filter((c) => c.status !== "Följs")
      .map((c) => ({
        id: `rule-${c.id}`,
        title: `${c.title} · ${c.propertyName}`,
        category: "Regelavvikelse",
        href: `/regler/kontroller/${c.id}`,
      })),
    ...bookings
      .filter((b) => b.contract === "Väntar" && b.state !== "Avslutad")
      .map((b) => ({
        id: `contract-${b.id}`,
        title: `Avtal saknas · ${b.guest} · ${b.unitLabel}`,
        category: "Avtal",
        href: `/bokningar/${b.id}`,
      })),
  ];

