  const feeFor = (b: (typeof bookings)[number]) => {
    const p = propertyById.get(b.propertyId);
    if (!p) return 0;
    return ownerFeeForBooking(p, b.nights, b.nights * b.nightly);
  };
  const intjanat = bookings
    .filter((b) => b.state !== "Avbokad")
    .reduce((sum, b) => sum + feeFor(b), 0);
