  const trend = economy.rows.map((r) => r.share);
  const forecastTrend = [...trend, Math.round(trend[trend.length - 1] * 1.25)];

  return (
    <Frame crumb={<span className="font-semibold text-foreground">Översikt</span>}>
      <div className="mb-7">
        <div className="text-xs font-semibold uppercase tracking-wide text-primary">
