      {/* UTHYRNING */}
      <SectionLabel>Uthyrning</SectionLabel>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <StatCard label="Kommande" value={kommande} detail="bokade vistelser" />
        <StatCard label="Pågående" value={pagaende} detail="just nu" accent />
        <StatCard label="Avslutade i år" value={avslutade} detail="genomförda" />
      </div>

      {/* BEHÖVER DIN UPPMÄRKSAMHET */}
      <SectionLabel className="mt-9">Behöver din uppmärksamhet</SectionLabel>
      <Card className="overflow-hidden">
        {attention.length > 0 ? (
          <div className="divide-y">
            <div className="flex items-center gap-3 bg-muted/40 px-5 py-2.5 text-[12px] font-semibold uppercase tracking-wide text-muted-foreground">
              <span className="flex-1">Åtgärd</span>
              <span className="w-36 shrink-0">Kategori</span>
            </div>
            {attention.map((item) => (
              <Link
                key={item.id}
                href={item.href}
                className="flex items-center gap-3 px-5 py-3.5 transition-colors hover:bg-muted/50"
              >
                <span className="size-2 shrink-0 rounded-full bg-[var(--warning)]" />
                <span className="min-w-0 flex-1 truncate text-sm font-medium">
                  {item.title}
                </span>
                <span className="w-36 shrink-0">
                  <Badge variant={item.category === "Störning" ? "warning" : "outline"}>
                    {item.category}
                  </Badge>
                </span>
                <ArrowRight className="size-4 shrink-0 text-muted-foreground" />
              </Link>
            ))}
          </div>
        ) : (
          <CardContent className="flex flex-col items-center justify-center py-12 text-center">
            <div className="text-[15px] font-semibold">Allt är under kontroll</div>
            <p className="mt-1 text-[13.5px] text-muted-foreground">
              Inget behöver din uppmärksamhet just nu.
            </p>
          </CardContent>
        )}
      </Card>

      {/* EKONOMI */}
      <SectionLabel className="mt-9">Ekonomi</SectionLabel>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div className="text-[13.5px] font-medium text-muted-foreground">
                Intjänat i år
              </div>
              <Badge variant="muted">föreningsavgift</Badge>
            </div>
