import { useMemo, useState } from "react";
import Link from "next/link";
import { CalendarRange, List } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

export type BookingRow = {
  id: string;
  unitLabel: string;
  propertyName: string;
  resident: string;
  guest: string;
  checkIn: string;
  checkOut: string;
  contract: string;
  state: string;
};

const STATUS_FILTERS = ["Alla", "Pågående", "Kommande", "Avslutad"];

const MONTHS: Record<string, number> = {
  jan: 0, feb: 1, mar: 2, apr: 3, maj: 4, jun: 5,
  jul: 6, aug: 7, sep: 8, okt: 9, nov: 10, dec: 11,
};
const TARGET_MONTH = 5; // juni
const DAYS = 30;
const MONTH_LABEL = "Juni 2026";

function parseDate(s: string) {
  const [d, m] = s.trim().split(/\s+/);
  return { day: parseInt(d, 10), month: MONTHS[(m ?? "").toLowerCase()] ?? TARGET_MONTH };
}
const clamp = (n: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, n));

export default function BookingsViews({ bookings }: { bookings: BookingRow[] }) {
  const [view, setView] = useState<"lista" | "kalender">("lista");
  const [status, setStatus] = useState("Alla");

  const filtered = useMemo(
    () => (status === "Alla" ? bookings : bookings.filter((b) => b.state === status)),
    [bookings, status],
  );

  // Build per-unit rows with a June segment for the calendar.
  const calRows = useMemo(() => {
    const byUnit = new Map<string, { unit: string; property: string; bars: BookingRow[] }>();
    for (const b of bookings) {
      const ci = parseDate(b.checkIn);
      const co = parseDate(b.checkOut);
      const start = ci.month < TARGET_MONTH ? 1 : ci.month === TARGET_MONTH ? ci.day : null;
      const end = co.month > TARGET_MONTH ? DAYS : co.month === TARGET_MONTH ? co.day : null;
      if (start === null || end === null) continue;
      if (!byUnit.has(b.unitLabel))
        byUnit.set(b.unitLabel, { unit: b.unitLabel, property: b.propertyName, bars: [] });
      byUnit.get(b.unitLabel)!.bars.push(b);
    }
    return Array.from(byUnit.values()).sort((a, b) => a.unit.localeCompare(b.unit));
  }, [bookings]);

  function barColor(state: string) {
    if (state === "Pågående") return "bg-primary text-primary-foreground";
    if (state === "Kommande") return "bg-accent text-accent-foreground";
    if (state === "Avbokad") return "bg-muted text-muted-foreground line-through";
    return "bg-muted text-muted-foreground";
  }

  function seg(b: BookingRow) {
    const ci = parseDate(b.checkIn);
    const co = parseDate(b.checkOut);
    const start = clamp(ci.month < TARGET_MONTH ? 1 : ci.day, 1, DAYS);
    const end = clamp(co.month > TARGET_MONTH ? DAYS : co.day, 1, DAYS);
    return { left: ((start - 1) / DAYS) * 100, width: ((end - start + 1) / DAYS) * 100 };
  }

  return (
    <>
      {/* view toggle */}
      <div className="mb-5 flex items-center justify-between gap-3">
        <div className="inline-flex rounded-lg border p-1">
          {([["lista", "Lista", List], ["kalender", "Kalender", CalendarRange]] as const).map(
            ([key, label, Icon]) => (
              <button
                key={key}
                onClick={() => setView(key)}
                className={
                  view === key
                    ? "inline-flex items-center gap-2 rounded-md bg-primary px-3.5 py-1.5 text-sm font-semibold text-primary-foreground"
                    : "inline-flex items-center gap-2 rounded-md px-3.5 py-1.5 text-sm font-medium text-muted-foreground hover:text-foreground"
                }
              >
                <Icon className="size-4" />
                {label}
              </button>
            ),
          )}
        </div>
        {view === "lista" ? (
          <div className="flex flex-wrap gap-2">
            {STATUS_FILTERS.map((f) => (
              <button
                key={f}
                onClick={() => setStatus(f)}
                className={
                  status === f
                    ? "inline-flex h-8 items-center rounded-full bg-foreground px-3.5 text-[13.5px] font-medium text-background"
                    : "inline-flex h-8 items-center rounded-full border bg-background px-3.5 text-[13.5px] font-medium text-muted-foreground hover:bg-muted"
                }
              >
                {f}
              </button>
            ))}
          </div>
        ) : (
          <span className="text-[13.5px] font-medium text-muted-foreground">{MONTH_LABEL}</span>
        )}
      </div>

      {view === "lista" ? (
        <Card>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Bokning</TableHead>
                <TableHead>Lägenhet · boende</TableHead>
                <TableHead>Gäst</TableHead>
                <TableHead>Datum</TableHead>
                <TableHead>Avtal</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Åtgärd</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filtered.map((b) => (
                <TableRow key={b.id} className="group">
                  <TableCell>
                    <Link href={`/bokningar/${b.id}`} className="font-semibold text-primary group-hover:underline">
                      {b.id}
                    </Link>
                  </TableCell>
                  <TableCell>
                    <span className="font-semibold">{b.unitLabel}</span>
                    <span className="text-muted-foreground"> · {b.resident}</span>
                  </TableCell>
                  <TableCell>{b.guest}</TableCell>
                  <TableCell className="whitespace-nowrap text-muted-foreground">
                    {b.checkIn}–{b.checkOut}
                  </TableCell>
                  <TableCell>
                    {b.contract === "Signerat" ? (
                      <Badge variant="success">BankID ✓</Badge>
                    ) : (
                      <Badge variant="warning">Väntar</Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    <Badge variant={b.state === "Pågående" ? "primary" : "muted"}>{b.state}</Badge>
                  </TableCell>
                  <TableCell className="text-right">
                    <Button asChild variant="outline" size="sm">
                      <Link href={`/bokningar/${b.id}`}>Öppna bokning</Link>
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
              {filtered.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} className="py-10 text-center text-[13.5px] text-muted-foreground">
                    Inga bokningar med den statusen.
                  </TableCell>
                </TableRow>
              ) : null}
            </TableBody>
          </Table>
        </Card>
      ) : (
        <Card className="overflow-hidden p-4">
          <div className="overflow-x-auto">
            <div className="min-w-[760px]">
              {/* day header */}
              <div className="flex border-b pb-2">
                <div className="w-40 shrink-0 text-[12px] font-semibold uppercase tracking-wide text-muted-foreground">
                  Lägenhet
                </div>
                <div className="relative flex flex-1">
                  {Array.from({ length: DAYS }, (_, i) => (
                    <div key={i} className="flex-1 text-center text-[10px] text-muted-foreground">
                      {i + 1}
                    </div>
                  ))}
                </div>
              </div>
              {/* rows */}
              {calRows.map((row) => (
                <div key={row.unit} className="flex items-center border-b py-2 last:border-0">
                  <div className="w-40 shrink-0 pr-3">
                    <div className="text-[13px] font-semibold">{row.unit}</div>
                    <div className="truncate text-[11px] text-muted-foreground">{row.property}</div>
                  </div>
                  <div className="relative h-8 flex-1">
                    {/* gridlines */}
                    <div className="absolute inset-0 flex">
                      {Array.from({ length: DAYS }, (_, i) => (
                        <div key={i} className="flex-1 border-r border-border/40 last:border-0" />
                      ))}
                    </div>
                    {/* booking bars */}
                    {row.bars.map((b) => {
                      const { left, width } = seg(b);
                      return (
                        <Link
                          key={b.id}
                          href={`/bokningar/${b.id}`}
                          title={`${b.guest} · ${b.checkIn}–${b.checkOut}`}
                          className={`absolute top-1 flex h-6 items-center overflow-hidden whitespace-nowrap rounded-md px-2 text-[11px] font-semibold ${barColor(b.state)}`}
                          style={{ left: `${left}%`, width: `calc(${width}% - 2px)` }}
                        >
                          {b.guest}
                        </Link>
                      );
                    })}
                  </div>
                </div>
              ))}
              {calRows.length === 0 ? (
                <div className="py-10 text-center text-[13.5px] text-muted-foreground">
                  Inga bokningar den här månaden.
                </div>
              ) : null}
            </div>
          </div>
          {/* legend */}
          <div className="mt-3 flex flex-wrap gap-4 px-1 text-[12px] text-muted-foreground">
            <span className="flex items-center gap-1.5"><span className="size-2.5 rounded bg-primary" /> Pågående</span>
            <span className="flex items-center gap-1.5"><span className="size-2.5 rounded bg-accent" /> Kommande</span>
            <span className="flex items-center gap-1.5"><span className="size-2.5 rounded bg-muted" /> Avslutad</span>
          </div>
        </Card>
      )}
    </>
  );
}
"}

